import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';

const transport = new StreamableHTTPClientTransport('http://are-sidecar:8000/mcp');
const client = new Client({ name: 'task-client', version: '1.0.0' }, { capabilities: {} });
await client.connect(transport);

// Check time
const timeResult = await client.callTool({ name: 'are_get_time', arguments: {} });
console.log('Time:', timeResult.content[0].text);

// List emails from Kjersti
const emailsResult = await client.callTool({ name: 'Emails__list_emails', arguments: {} });
const emails = JSON.parse(emailsResult.content[0].text);
const kjerstiEmails = emails.result.emails.filter(e => e.sender === 'kjersti.fjellstad@uit.no');
console.log('Kjersti emails count:', kjerstiEmails.length);

await client.close();
EOF
